<script setup>
import Icon from './Icon.vue'
import {formatPrice,thumbUrl} from '../lib/domain'
import placeholder from '../assets/placeholder-property.svg'
defineProps({property:Object,favorite:Boolean,manage:Boolean,brand:Object})
defineEmits(['open','favorite','edit'])
</script>
<template><article class="property-card"><div class="property-photo"><img v-if="property.image" :src="thumbUrl(property.image)" :alt="property.type + ' en ' + property.commune" loading="lazy" decoding="async" @error="$event.target.style.display='none'"><img v-else :src="placeholder" alt="" class="photo-placeholder"><span class="photo-label" :class="property.operation==='Arriendo' ? 'rent' : 'sale'">{{property.operation}}</span><button v-if="!manage" class="favorite" :class="{selected:favorite}" :aria-label="favorite ? 'Quitar de favoritos' : 'Guardar en favoritos'" :aria-pressed="favorite" @click="$emit('favorite',property.id)"><Icon name="heart"/></button><span v-else class="photo-status">{{property.status}}</span></div><div class="property-body"><span class="card-kind">{{property.type}} en {{property.operation.toLowerCase()}}</span><strong class="card-price">{{formatPrice(property)}}</strong><button class="card-title" @click="$emit('open',property)">{{property.title}}</button><div class="property-location"><Icon name="pin"/>{{property.sector ? property.commune + ' · ' + property.sector : property.commune}}</div><div class="property-bottom"><div class="property-specs"><span v-if="property.beds>0"><Icon name="bed"/>{{property.beds}} dorm.</span><span v-if="property.baths>0"><Icon name="bath"/>{{property.baths}} {{property.baths==1?'baño':'baños'}}</span><span><Icon name="area"/>{{property.area}} m²</span></div><button v-if="manage" class="text-button" @click="$emit('edit',property)">Administrar<Icon name="arrow"/></button><button v-else class="round-arrow" :aria-label="'Ver ' + property.title" @click="$emit('open',property)"><Icon name="arrow"/></button></div><div v-if="brand?.name" class="publication-brand"><img v-if="brand.logo" :src="brand.logo" alt="" @error="$event.target.style.display='none'"><span>{{brand.name}}</span></div></div></article></template>
